      "path": "packages/plugin/src/pool/dispatcher.ts",
      "content": "/**\n * PoolRoutingDispatcher — the undici global-dispatcher layer for the exit\n * pool (docs/ip-pool.md section 2).\n *\n * Shape copied from dsh-llm-proxy's RoutingDispatcher (verified there\n * against the same host); selection logic differs: instead of a static\n * host set, every request consults ExitPool.pick() (pinned-first, session\n * stickiness, rotation over two-tier health).\n *\n * One routing decision per request, synchronous and IO-free (pick is pure).\n * Failures are NOT retried here — the 429/403 rotation loop (3.4) is the\n * pi-ai-callable layer's job; this dispatcher only routes. It implements\n * the undici Dispatcher subset `fetch` uses (dispatch/close/destroy),\n * same contract dsh-llm-proxy validated.\n */\n\nimport { AsyncLocalStorage } from 'node:async_hooks'\n\nimport { Agent, ProxyAgent, type Dispatcher } from 'undici'\n\nimport type { ExitPool } from './pool.ts'\n\n/** Structural seam over npm undici so tests can inject fakes. */\nexport interface UndiciSeam {\n  Agent: typeof Agent\n  ProxyAgent: typeof ProxyAgent\n  setGlobalDispatcher(dispatcher: Dispatcher): unknown\n  getGlobalDispatcher(): Dispatcher\n  /**\n   * The module's own fetch (honors THIS module's global-dispatcher state).\n   * Live-observed 2026-09-09 (docs/ip-pool.md R2): Node's built-in fetch\n   * reads a SEPARATE built-in undici instance's dispatcher slot —\n   * setGlobalDispatcher on the npm module never reaches it, and the OpenAI\n   * SDK inside pi-ai captures globalThis.fetch at call time, so without\n   * this swap the pool's routing silently never applies to model traffic.\n   * Typed loosely on purpose: npm undici's Request/Response element types\n   * never structurally match Node's built-ins across versions.\n   */\n  fetch?: (input: unknown, init?: unknown) => Promise<unknown>\n}\n\nexport interface RoutingContext {\n  /** Model id for the in-flight call (two-tier health needs it, 3.3). */\n  model?: string\n  /** Inbound session id (stickiness key, 3.3). */\n  session?: string\n}\n\n/** Per-request routing context (docs/ip-pool.md 3.3): pi-ai builds the body\n *  and dispatches on separate layers with no model channel between them, so\n *  the adapter sets this at stream() entry and the dispatcher reads it. */\nexport const routingContext = new AsyncLocalStorage<RoutingContext>()\n\nexport interface PoolRoutingOptions {\n  pool: ExitPool\n  undici: UndiciSeam\n  /** Hosts whose traffic goes through the pool; everything else is direct. */\n  proxyHosts?: string[]\n  /** Per-exit ProxyAgent cache LRU cap (connection setup is lazy). */\n  agentLruCap?: number\n  /** Response-silence sentinel, window (a): dispatch -> first callback (docs §4.3; default 2s, test-injectable). */\n  sentinelMs?: number\n  /** Sentinel window (b): tunnel established -> response headers. The tunnel\n   *  standing proves exit liveness; the rest of the wait is the LLM upstream\n   *  composing the first token (measured 1.7-2.7s live), so this window is\n   *  far looser than (a). Default 10s, test-injectable. */\n  headersMs?: number\n  /** Log sink for routing decisions (diagnostics). */\n  logger?: { warn(message: string): void }\n}\n\nconst DEFAULT_PROXY_HOSTS = ['opencode.ai']\nconst PROXY_PROTOCOL_PREFIX = /^[a-z0-9+.-]+:\\/\\//i\n\n/** 'host:port' -> 'host' (bracket-aware) for host matching. */\nexport function normalizeHost(host: string): string {\n  if (!host) return ''\n  let value = host.trim().toLowerCase()\n  if (value.includes('://')) {\n    try {\n      value = new URL(value).hostname\n    } catch {\n      /* fall through to the regex strip */\n    }\n  }\n  return value.replace(/:\\d+$/, '').replace(/^\\[(.+)\\]$/, '$1')\n}\n\nexport function isLoopback(host: string): boolean {\n  const normalized = normalizeHost(host)\n  return normalized === 'localhost' || normalized === '127.0.0.1' || normalized === '::1'\n}\n\n/** Map an exit address to a ProxyAgent URI ('h:1' -> 'http://h:1'). */\nexport function exitProxyUri(exitId: string, protocol: 'http' | 'socks5'): string {\n  const scheme = protocol === 'socks5' ? 'socks5' : 'http'\n  return PROXY_PROTOCOL_PREFIX.test(exitId) ? exitId : `${scheme}://${exitId}`\n}\n\n/**\n * The undici Dispatcher surface `fetch` actually calls (the subset\n * dsh-llm-proxy's RoutingDispatcher implements — full `Dispatcher` carries\n * 20+ stream helpers we never hit through fetch).\n */\nexport interface RoutingDispatcherSurface {\n  dispatch(options: Dispatcher.DispatchOptions, handler: Dispatcher.DispatchHandler): boolean\n  close(): Promise<void>\n  destroy(): Promise<void>\n}\n\nexport class PoolRoutingDispatcher implements RoutingDispatcherSurface {\n  #pool: ExitPool\n  #undici: UndiciSeam\n  #proxyHosts: Set<string>\n  #agentLruCap: number\n  #sentinelMs: number\n  #headersMs: number\n  #logger?: { warn(message: string): void }\n  /** Direct path for non-pool hosts and loopback. */\n  #direct: Dispatcher\n  /** LRU of per-exit ProxyAgents (docs/ip-pool.md 2, exit multi-instance). */\n  #agents = new Map<string, Dispatcher>()\n  #agentsOrder: string[] = []\n  #closed = false\n\n  constructor(options: PoolRoutingOptions) {\n    this.#pool = options.pool\n    this.#undici = options.undici\n    this.#proxyHosts = new Set(\n      (options.proxyHosts ?? DEFAULT_PROXY_HOSTS).map((host) => normalizeHost(host)),\n    )\n    this.#agentLruCap = options.agentLruCap ?? 16\n    this.#sentinelMs = options.sentinelMs ?? 2_000\n    this.#headersMs = options.headersMs ?? 10_000\n    this.#logger = options.logger\n    this.#direct = new options.undici.Agent()\n  }\n\n  /** Live re-apply of the proxied-host list (settings page, docs §5.1). */\n  setProxyHosts(hosts: string[] | undefined): void {\n    const next = hosts && hosts.length > 0\n      ? new Set(hosts.map((host) => normalizeHost(host)))\n      : new Set(DEFAULT_PROXY_HOSTS.map((host) => normalizeHost(host)))\n    this.#proxyHosts = next\n  }\n\n  /** The proxied-host set as configured (diagnostics / status bridge). */\n  get proxyHosts(): readonly string[] {\n    return [...this.#proxyHosts]\n  }\n\n  /** The agent for one exit, LRU-capped (docs/ip-pool.md 2). */\n  #agentFor(exitId: string): Dispatcher | null {\n    const cached = this.#agents.get(exitId)\n    if (cached) {\n      const index = this.#agentsOrder.indexOf(exitId)\n      if (index >= 0) this.#agentsOrder.splice(index, 1)\n      this.#agentsOrder.push(exitId)\n      return cached\n    }\n    const exit = this.#pool.get(exitId)\n    if (!exit) return null\n    try {\n      // dsh-llm-proxy's measured keep-alive pitfall (routing-dispatcher.js):\n      // the ProxyAgent's proxy-side pool reuses silently-dead CONNECT\n      // tunnels; pipelining: 0 forces a fresh tunnel per request.\n      const seam = this.#undici\n      const agent = new seam.ProxyAgent({\n        uri: exitProxyUri(exit.id, exit.protocol),\n        clientFactory: (origin: URL | string, opts?: unknown) =>\n          new seam.Agent({ ...(opts as object), pipelining: 0 }),\n      })\n      this.#agents.set(exitId, agent)\n      this.#agentsOrder.push(exitId)\n      if (this.#agentsOrder.length > this.#agentLruCap) {\n        const evict = this.#agentsOrder.shift()\n        if (evict !== undefined) {\n          const old = this.#agents.get(evict)\n          this.#agents.delete(evict)\n          void old?.destroy().catch(() => {})\n        }\n      }\n      return agent\n    } catch (err) {\n      this.#logger?.warn(`dsh-plugin-adapter: failed to build proxy agent for ${exitId}: ${err instanceof Error ? err.message : String(err)}`)\n      return null\n    }\n  }\n\n  dispatch(options: Dispatcher.DispatchOptions, handler: Dispatcher.DispatchHandler): boolean {\n    if (this.#closed) {\n      handler.onResponseError?.({} as Dispatcher.DispatchController, new Error('dsh-plugin-adapter: routing dispatcher closed'))\n      return false\n    }\n    const origin = String(options.origin ?? '')\n    const host = normalizeHost(origin)\n    if (isLoopback(host) || !this.#proxyHosts.has(host)) {\n      return this.#direct.dispatch(options, handler)\n    }\n    const context = routingContext.getStore() ?? {}\n    const model = context.model ?? 'default'\n    const session = context.session ?? 'default'\n    const exitId = this.#pool.pick(session, model)\n    if (exitId === null) {\n      // Pool unusable (empty / all cooling): direct, never fail closed (3.3).\n      return this.#direct.dispatch(options, handler)\n    }\n    const agent = this.#agentFor(exitId)\n    if (!agent) {\n      return this.#direct.dispatch(options, handler)\n    }\n    return agent.dispatch(options, this.#observe(exitId, model, session, handler))\n  }\n\n  /**\n   * Wrap the downstream handler with the passive-signal observer\n   * (docs/ip-pool.md §4.2 rule table, §4.3 被动): the real request's own\n   * outcome feeds the two-tier health — free liveness data no probe spends\n   * quota on. Body bytes stream through untouched; only the response start\n   * line and terminal transport errors are read.\n   *\n   * Forwarding discipline (measured against undici 8.10 on this host): the\n   * fetch handler's methods live on a prototype with private state, so a\n   * spread would strip them and Object.create delegation would re-enter\n   * them with the wrong `this`. The wrapper is a fresh plain object that\n   * forwards every DispatchHandler callback to the original with the\n   * original as `this` — the same shape undici's own wrappers use.\n   *\n   * Response-silence sentinel: undici's Pool fires NONE of the handler\n   * callbacks (not even onResponseError) when a proxy CONNECT fails at the\n   * connection stage — the failure surfaces only as a fetch rejection (and\n   * an APIConnectionError/\"Connection error.\" upstream). Without a fallback\n   * the passive signal is blind exactly when a dead exit needs to be evicted\n   * (live repro: 10.255.255.1:9999 blackhole, seen:[] callbacks). So the\n   * wrapper arms a timer at dispatch time; any handler callback disarms it,\n   * and silence past the deadline counts as a transport failure (dead strike\n   * + session reroute). The sentinel never aborts the request itself — fetch\n   * and pi-ai own their own timeouts.\n   */\n  #observe(exitId: string, model: string, session: string, handler: Dispatcher.DispatchHandler): Dispatcher.DispatchHandler {\n    const pool = this.#pool\n    const forward = (method: keyof Dispatcher.DispatchHandler, args: unknown[]): void => {\n      const fn = handler[method]\n      if (typeof fn === 'function') (fn as (...a: unknown[]) => void).apply(handler, args)\n    }\n    let classified = false\n    const classify = (statusCode: number): void => {\n      if (classified) return\n      classified = true\n      const verdict = pool.recordPassive(exitId, statusCode, model)\n      // A degraded sticky exit must not keep the session pinned to it.\n      if (verdict !== 'ok') pool.rerouteSession(session)\n    }\n    // The most recent controller the wrapper has seen (undici hands a fresh\n    // one to each handler callback; abort must go to the live one).\n    let liveController: { abort?(reason: Error): void } | null = null\n    const classifyTransport = (): void => {\n      if (classified) return\n      classified = true\n      pool.recordPassiveTransport(exitId)\n      pool.rerouteSession(session)\n      // Live-observed (2026-09-07, muse via 7897): after the tunnel stands a\n      // dead-behind-the-tunnel exit answers NOTHING — no headers, no\n      // onResponseError — and neither fetch nor pi-ai owns a body-silence\n      // timeout, so the request hangs forever (the turn never finished; the\n      // stop button's abort never reached it). The sentinel therefore does\n      // more than bookkeeping: it tears the dispatch down BOTH ways — abort\n      // the controller when we have one, and when the blackhole path never\n      // handed us a single callback (no controller exists) synthesize the\n      // response-error the handler owes, so fetch rejects at once, pi-ai\n      // turns that into an error event, and the adapter's rotate loop gets\n      // to move the session to a live exit.\n      const reason = new Error('dsh-plugin-adapter: exit response silence')\n      if (typeof handler.onResponseError === 'function') {\n        ;(handler.onResponseError as (c: unknown, e: Error) => void).call(handler, liveController ?? ({} as never), reason)\n      }\n      liveController?.abort?.(reason)\n    }\n    // Silence deadline, in two windows: (a) dispatch -> first callback (dead\n    // CONNECT fires NONE, undici 8.10 measured); (b) tunnel established ->\n    // response headers (onRequestStart disarms window (a) only). Window (b)\n    // must be MUCH looser than (a): the tunnel standing proves the exit is\n    // alive, and the remaining wait is the LLM upstream composing the first\n    // token — measured live 2026-09-09 (mihomo 7897 -> SJ exit -> zen):\n    // headers landed 1.7-2.7s after onRequestStart, so a 2s window (b) kills\n    // healthy streams (live repro: status 200 with TTFB 2.66s struck dead\n    // at 2s). Body pacing stays uncovered (a live stream disarms at\n    // onResponseStart); (a) keeps sitting under the host's 1-5s retry\n    // cadence and the coarse-screen latency gate (3s).\n    const armSentinel = (): void => {\n      clearTimeout(sentinel)\n      const window = sawRequestStart ? this.#headersMs : this.#sentinelMs\n      sentinel = setTimeout(classifyTransport, window)\n      sentinel.unref?.()\n    }\n    let sawRequestStart = false\n    let sentinel: NodeJS.Timeout | undefined = undefined\n    armSentinel()\n    const disarm = (): void => {\n      clearTimeout(sentinel)\n    }\n    return {\n      onRequestStart: (controller, context) => {\n        liveController = controller\n        // window (a) ends; window (b) begins: headers must still arrive,\n        // on the looser upstream-composition budget (see armSentinel)\n        sawRequestStart = true\n        armSentinel()\n        forward('onRequestStart', [controller, context])\n      },\n      onRequestUpgrade: (controller, statusCode, headers, socket) => {\n        liveController = controller\n        disarm()\n        forward('onRequestUpgrade', [controller, statusCode, headers, socket])\n      },\n      onResponseStart: (controller, statusCode, headers, statusMessage) => {\n        liveController = controller\n        disarm()\n        classify(statusCode)\n        forward('onResponseStart', [controller, statusCode, headers, statusMessage])\n      },\n      onResponseData: (controller, chunk) => {\n        liveController = controller\n        forward('onResponseData', [controller, chunk])\n      },\n      onResponseEnd: (controller, trailers) => {\n        liveController = controller\n        disarm()\n        forward('onResponseEnd', [controller, trailers])\n      },\n      onResponseError: (controller, error) => {\n        liveController = controller\n        disarm()\n        classifyTransport()\n        forward('onResponseError', [controller, error])\n      },\n      onResponseStarted: () => {\n        disarm()\n        forward('onResponseStarted', [])\n      },\n      onBodySent: (chunk) => forward('onBodySent', [chunk]),\n      onRequestSent: () => forward('onRequestSent', []),\n    }\n  }\n\n  close(): Promise<void> {\n    this.#closed = true\n    const jobs = [this.#direct.close(), ...[...this.#agents.values()].map((a) => a.close())]\n    return Promise.all(jobs).then(() => undefined)\n  }\n\n  destroy(): Promise<void> {\n    this.#closed = true\n    const jobs = [this.#direct.destroy(), ...[...this.#agents.values()].map((a) => a.destroy())]\n    this.#agents.clear()\n    this.#agentsOrder = []\n    return Promise.all(jobs).then(() => undefined)\n  }\n}\n"
    },
    {
      "path": "packages/plugin/src/pool/admission.ts",
      "content": "/**\n * Admission probe — the gate a free-source candidate must pass before it\n * becomes an ExitNode (docs/ip-pool.md 4.5). Four steps, fail-fast:\n *\n *   1. connectivity + latency   (via the candidate, GET an IP echo endpoint)\n *   2. exit IP + geo            (same response; also the pool's routing key)\n *   3. HTTPS tunnel             (via the candidate, GET the Zen models list —\n *                                probing the real target beats generic test\n *                                sites, and a forged 200 cannot fake step 4)\n *   4. anonymous-lane smoke     (1-token chat via the candidate)\n *\n * All requests carry their own ProxyAgent (per-request dispatch, verified\n * against npm undici): the admission path never touches the global\n * dispatcher. manual/subscription/goproxy candidates skip steps 1-3 and run\n * step 4 only (their node facts already exist); pinned nodes are admitted\n * with warnings instead of rejections (the user vouches, 3.1).\n */\n\nimport type { Dispatcher } from 'undici'\n\nimport { ZEN_BASE_URL } from '../adapter/catalog.ts'\nimport { FREE_LANE_GATE_TOOL_NAMES, freeLaneGateTool } from '../adapter/messages.ts'\nimport { canonicalSessionID, disguiseHeaders, opencodeUserAgent, randomID, stableID } from '../adapter/ids.ts'\nimport { gradeOf, type ExitNode, type ExitPool } from './pool.ts'\n\nexport interface AdmissionDeps {\n  pool: ExitPool\n  undici: {\n    ProxyAgent: new (options: { uri: string; clientFactory?: (origin: URL | string, options?: unknown) => unknown }) => Dispatcher\n    request(url: string, options: { dispatcher: Dispatcher; method?: string; headers?: Record<string, string>; body?: string }): Promise<{ statusCode: number; body: { text(): Promise<string> } }>\n  }\n  /** zen endpoint override for tests. */\n  zenBaseUrl?: string\n  /** ip echo override for tests. */\n  ipEchoUrl?: string\n  /** chat model for the smoke request (probeModels[0] upstream). */\n  smokeModel?: string\n  timeoutMs?: number\n  blockedCountries?: string[]\n  logger?: { warn(message: string): void }\n}\n\nexport interface EchoFacts {\n  exitIP: string\n  exitLocation: string\n  latencyMs: number\n}\n\n/**\n * Coarse screen (admission steps 1+2, docs/ip-pool.md 4.5 修订): one request\n * through the candidate to the ip echo. This step touches only the wild\n * candidate and a public IP service — never the anonymous lane — so callers\n * may fan it out at high concurrency (admissionFanout; GoProxy uses 300 for\n * the same reason). Steps 3-4 (which spend anonymous-lane quota) stay on the\n * bounded Prober.\n */\nexport async function coarseScreen(\n  deps: Pick<AdmissionDeps, 'undici' | 'ipEchoUrl' | 'blockedCountries' | 'logger'>,\n  candidate: { address: string; protocol: 'http' | 'socks5' },\n  options: { relaxed?: boolean; pinned?: boolean; timeoutMs?: number } = {},\n): Promise<EchoFacts | { rejected: string }> {\n  const ipEcho = deps.ipEchoUrl ?? DEFAULT_IP_ECHO\n  const timeout = options.timeoutMs ?? DEFAULT_TIMEOUT_MS\n  const blocked = new Set(deps.blockedCountries ?? ['CN'])\n  const maxResponseMs = options.relaxed ? RELAXED_RESPONSE_MS : 3_000\n\n  let agent: Dispatcher | null = null\n  try {\n    agent = new deps.undici.ProxyAgent({\n      uri: candidate.protocol === 'socks5' ? `socks5://${candidate.address}` : `http://${candidate.address}`,\n    })\n  } catch (err) {\n    return { rejected: `agent-build: ${err instanceof Error ? err.message : String(err)}` }\n  }\n  try {\n    const started = Date.now()\n    const echo = await withTimeout(\n      deps.undici.request(ipEcho, { dispatcher: agent }),\n      timeout,\n      'probe',\n    )\n    const latencyMs = Date.now() - started\n    if (echo.statusCode !== 200) return { rejected: `echo HTTP ${echo.statusCode}` }\n    let body: EchoResponse\n    try {\n      body = JSON.parse(await echo.body.text()) as EchoResponse\n    } catch {\n      return { rejected: 'echo body not JSON' }\n    }\n    if (body.status !== 'success' || !body.query) return { rejected: 'echo did not report an exit IP' }\n    const country = body.countryCode?.toUpperCase() ?? ''\n    if (blocked.has(country)) return { rejected: `geo-blocked ${country}` }\n    if (latencyMs > maxResponseMs && !options.pinned) {\n      return { rejected: `latency ${latencyMs}ms > ${maxResponseMs}ms` }\n    }\n    return {\n      exitIP: body.query,\n      exitLocation: `${body.countryCode} ${body.city}`.trim(),\n      latencyMs,\n    }\n  } catch (err) {\n    return { rejected: err instanceof Error ? err.message : String(err) }\n  } finally {\n    void agent.close().catch(() => {})\n  }\n}\n\n/** Bounded fan-out helper for the coarse screen (wild candidates only).\n *  onProgress reports (screensCompleted, survivorsSoFar) as the fan-out runs\n *  (settings-page refill progress, docs §5.3). */\nexport async function coarseScreenBatch(\n  deps: Parameters<typeof coarseScreen>[0],\n  candidates: Array<{ address: string; protocol: 'http' | 'socks5' }>,\n  options: { fanout?: number; relaxed?: boolean; timeoutMs?: number; onProgress?: (done: number, passed: number) => void } = {},\n): Promise<Map<string, EchoFacts>> {\n  const fanout = Math.max(1, options.fanout ?? 300)\n  const results = new Map<string, EchoFacts>()\n  const queue = [...candidates]\n  let done = 0\n  const worker = async (): Promise<void> => {\n    for (;;) {\n      const candidate = queue.shift()\n      if (candidate === undefined) return\n      const verdict = await coarseScreen(deps, candidate, options)\n      done += 1\n      if ('exitIP' in verdict) results.set(candidate.address, verdict)\n      options.onProgress?.(done, results.size)\n    }\n  }\n  await Promise.all(Array.from({ length: Math.min(fanout, candidates.length) }, () => worker()))\n  return results\n}\n\ninterface EchoResponse {\n  status: string\n  query: string\n  countryCode: string\n  city: string\n}\n\nconst DEFAULT_IP_ECHO = 'http://ip-api.com/json/?fields=status,country,countryCode,city,query'\nconst DEFAULT_TIMEOUT_MS = 8_000\n/** critical-state relaxed latency gate (docs/ip-pool.md 4.6 maxResponseMs). */\nconst RELAXED_RESPONSE_MS = 6_000\n\nfunction withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {\n  return new Promise<T>((resolve, reject) => {\n    const timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms)\n    promise.then(\n      (value) => {\n        clearTimeout(timer)\n        resolve(value)\n      },\n      (err) => {\n        clearTimeout(timer)\n        reject(err)\n      },\n    )\n  })\n}\n\n/** One admission probe for one candidate address. Pure effects: returns the\n *  verdict; the caller (refill scheduler) applies it to the pool. */\nexport interface AdmissionResult {\n  admitted: boolean\n  node?: ExitNode\n  /** Step that rejected the candidate, with the reason (diagnostics). */\n  reason?: string\n  /**\n   * The candidate passed every step except quota: alive proxy, working Zen\n   * tunnel, 429 at smoke (2026-09-05 decision: these are good exits whose\n   * quota is consumed elsewhere — free proxies are shared worldwide). The\n   * caller admits them and immediately cools them (markLimited), so the\n   * periodic probe retries when the cooldown expires.\n   */\n  limited?: boolean\n}\n\nexport async function admitCandidate(\n  deps: AdmissionDeps,\n  candidate: { address: string; protocol: 'http' | 'socks5'; source: ExitNode['source'] },\n  options: {\n    relaxed?: boolean\n    pinned?: boolean\n    timeoutMs?: number\n    /** Pre-screened echo facts (coarseScreen output): skips steps 1-2. */\n    echoFacts?: EchoFacts\n  } = {},\n): Promise<AdmissionResult> {\n  const zenBase = deps.zenBaseUrl ?? ZEN_BASE_URL\n  const timeout = options.timeoutMs ?? DEFAULT_TIMEOUT_MS\n  const smokeModel = deps.smokeModel ?? 'big-pickle'\n  // Live-observed 2026-09-09: zen now REJECTS anonymous-lane chat without\n  // the CLI session headers (400 MissingSessionID \"can only be used in\n  // OpenCode\") — the smoke request must carry the same disguise set the\n  // adapter sends, or every candidate fails step 4 regardless of exit\n  // quality (a full refill round admitted 0 of 701 tunnel-OK survivors).\n  // Per-candidate ids: the upstream correlates sessions with exits, so a\n  // probe session must not collide with real adapter sessions. The canonical\n  // mapping (ids.ts) is mandatory here too — the old 24-hex probe sessions\n  // drew 403 FreeTierError on the free lane like every other foreign shape.\n  const probeHeaders = disguiseHeaders({\n    session: canonicalSessionID(`admission:${candidate.address}`),\n    request: randomID('req', 16),\n    project: stableID('prj', 'opencode2dsh:default-project'),\n    parentSession: '',\n  })\n\n  let agent: Dispatcher | null = null\n  try {\n    agent = new deps.undici.ProxyAgent({\n      uri: candidate.protocol === 'socks5' ? `socks5://${candidate.address}` : `http://${candidate.address}`,\n    })\n  } catch (err) {\n    return { admitted: false, reason: `agent-build: ${err instanceof Error ? err.message : String(err)}` }\n  }\n\n  const request = (url: string, init: { method?: string; headers?: Record<string, string>; body?: string } = {}) =>\n    withTimeout(\n      deps.undici.request(url, { dispatcher: agent!, ...init }),\n      timeout,\n      init.method === 'POST' ? 'smoke' : 'probe',\n    )\n\n  try {\n    // Steps 1+2 run inline only when the caller has not pre-screened the\n    // candidate (coarseScreen/batch output = echoFacts; the refill loop\n    // always pre-screens free candidates at high fan-out).\n    let facts: EchoFacts\n    if (options.echoFacts) {\n      facts = options.echoFacts\n    } else {\n      const verdict = await coarseScreen(deps, candidate, options)\n      if ('rejected' in verdict) return { admitted: false, reason: verdict.rejected }\n      facts = verdict\n    }\n\n    // Step 3: HTTPS tunnel to the real upstream (models list, Bearer public).\n    const models = await request(`${zenBase.replace(/\\/+$/, '')}/v1/models`, {\n      headers: { authorization: 'Bearer public', 'user-agent': opencodeUserAgent(), 'x-opencode-client': 'cli', accept: 'application/json', ...probeHeaders },\n    })\n    if (models.statusCode !== 200) {\n      return { admitted: false, reason: `zen models HTTP ${models.statusCode}` }\n    }\n\n    // Step 4: anonymous-lane smoke (streaming, 1 token). The free lane\n    // rejects non-streaming bodies outright and wants the agent-shape gate\n    // tools in the body (adapter/messages.ts, live-probed 2026-09-18) — a\n    // bare 1-token probe 403s like every toolless chat.\n    const smoke = await request(`${zenBase.replace(/\\/+$/, '')}/v1/chat/completions`, {\n      method: 'POST',\n      headers: {\n        authorization: 'Bearer public',\n        'content-type': 'application/json',\n        'user-agent': opencodeUserAgent(),\n        'x-opencode-client': 'cli',\n        ...probeHeaders,\n      },\n      body: JSON.stringify({\n        model: smokeModel,\n        messages: [{ role: 'user', content: 'ping' }],\n        max_tokens: 1,\n        stream: true,\n        stream_options: { include_usage: true },\n        tools: FREE_LANE_GATE_TOOL_NAMES.map((name) => freeLaneGateTool(name)),\n        tool_choice: 'none',\n      }),\n    })\n    if (smoke.statusCode !== 200) {\n      // 429 = the exit is good (alive + tunnel verified) but its anonymous\n      // quota is currently consumed. Admit with limited: the caller cools it\n      // and the periodic probe retries later (measured 2026-09-05: 429 is\n      // the single largest smoke failure among tunnel-OK survivors).\n      if (smoke.statusCode === 429) {\n        return {\n          admitted: true,\n          limited: true,\n          reason: `zen smoke HTTP 429`,\n          node: {\n            id: candidate.address,\n            protocol: candidate.protocol,\n            source: candidate.source,\n            pinned: options.pinned ?? false,\n            exitIP: facts.exitIP,\n            exitLocation: facts.exitLocation,\n            latencyMs: facts.latencyMs,\n            quality: gradeOf(facts.latencyMs),\n            addedAt: Date.now(),\n          },\n        }\n      }\n      return { admitted: false, reason: `zen smoke HTTP ${smoke.statusCode}` }\n    }\n\n    return {\n      admitted: true,\n      node: {\n        id: candidate.address,\n        protocol: candidate.protocol,\n        source: candidate.source,\n        pinned: options.pinned ?? false,\n        exitIP: facts.exitIP,\n        exitLocation: facts.exitLocation,\n        latencyMs: facts.latencyMs,\n        quality: gradeOf(facts.latencyMs),\n        addedAt: Date.now(),\n      },\n    }\n  } catch (err) {\n    return { admitted: false, reason: err instanceof Error ? err.message : String(err) }\n  } finally {\n    void agent.close().catch(() => {})\n  }\n}\n\n/** Admit a trusted-source candidate (manual/subscription/goproxy): smoke\n *  only; failure warns instead of rejecting for pinned (docs 4.5). Existing\n *  pool facts are PRESERVED on the failure fallback — a failed smoke wipes\n *  neither a previously measured exitIP/latency nor the routing key. */\nexport async function admitTrusted(\n  deps: AdmissionDeps,\n  candidate: { address: string; protocol: 'http' | 'socks5'; source: 'manual' | 'subscription' | 'goproxy' },\n  options: { pinned?: boolean; previous?: { exitIP: string; exitLocation: string; latencyMs: number; quality?: ExitNode['quality'] } } = {},\n): Promise<AdmissionResult> {\n  const result = await admitCandidate(deps, candidate, { pinned: options.pinned })\n  if (result.admitted) return result\n  // Trusted candidates: keep the node (the address is the routing key\n  // fallback, 3.1), warn, and let periodic probing revisit.\n  deps.logger?.warn(`dsh-plugin-adapter: trusted exit ${candidate.address} failed admission (${result.reason}); admitted with ${options.previous?.exitIP ? 'previous' : 'unknown'} exit facts`)\n  const previous = options.previous\n  return {\n    admitted: true,\n    node: {\n      id: candidate.address,\n      protocol: candidate.protocol,\n      source: candidate.source,\n      pinned: options.pinned ?? false,\n      exitIP: previous?.exitIP ?? '',\n      exitLocation: previous?.exitLocation ?? '',\n      latencyMs: previous?.latencyMs ?? 0,\n      quality: previous?.quality ?? gradeOf(previous?.latencyMs ?? 0),\n      addedAt: Date.now(),\n    },\n  }\n}\n"
    },
    {
      "path": "packages/plugin/src/pool/pool.ts",
      "content": "/**\n * ExitPool — the exit-node table plus two-tier health and the four-state\n * refill machine (docs/ip-pool.md section 3).\n *\n * Tier 1, per-exit (ExitHealth): 429 cooldown + dead marking. Anonymous\n * quota is metered per exit IP (design.md section 3), so a 429 cools the\n * whole exit while other exits keep serving.\n *\n * Tier 2, per-(exit x model) (ModelBan): 401/403 refusals are usually\n * model-level (region blocks, delisting — see the muse/hy3 notes in\n * catalog.ts), so they ban only that pairing and never cool the exit.\n *\n * The pool is pure state: no IO, no timers. The prober, the dispatcher and\n * the refill scheduler all drive it through the mark* methods and read it\n * through pick()/snapshot(). injectable now() keeps the cooldown math\n * unit-testable.\n */\n\nexport type ExitSource = 'free' | 'manual' | 'subscription' | 'goproxy'\n\nexport interface ExitNode {\n  /** host:port, unique inside the pool (the address we dial). */\n  id: string\n  protocol: 'http' | 'socks5'\n  source: ExitSource\n  /** Fixed primary exit (docs/ip-pool.md 3.6). */\n  pinned: boolean\n  /** Empty for pinned nodes whose admission could not read it (3.1). */\n  exitIP: string\n  exitLocation: string\n  latencyMs: number\n  quality: 'S' | 'A' | 'B' | 'C'\n  addedAt: number\n}\n\nexport type ExitState = 'unknown' | 'ok' | 'dead'\nexport type BanState = 'ok' | 'suspect' | 'banned'\n\ninterface ExitHealth {\n  state: ExitState\n  lastProbedAt: number\n  consecutiveLimited: number\n  /** 429 cooldown deadline (epoch ms); 0 = not cooling. */\n  cooldownUntil: number\n  /** Serial-probe lock slot: at most one in-flight probe per exit (4.1). */\n  inflight: boolean\n  /** Consecutive dead rechecks; eviction after deadEvictions (3.5). */\n  deadStrikes: number\n}\n\ninterface ModelBan {\n  state: BanState\n  bannedAt: number\n  consecutiveFailures: number\n}\n\nexport type PoolState = 'healthy' | 'warning' | 'critical' | 'emergency'\n\nexport interface PoolOptions {\n  /** Free-pool target capacity (docs/ip-pool.md 3.5). Free-source nodes only. */\n  targetSize?: number\n  /** First 429 cooldown. */\n  limitedCooldownBaseMs?: number\n  /** Exponential backoff ceiling. */\n  limitedCooldownMaxMs?: number\n  /** Suspect -> banned after this many consecutive 401/403. */\n  modelBanConfirmations?: number\n  /** Dead exits are evicted after this many probe strikes (free source only). */\n  deadEvictions?: number\n  now?: () => number\n}\n\n/** Quality grade from admission latency (GoProxy thresholds). */\nexport function gradeOf(latencyMs: number): ExitNode['quality'] {\n  if (latencyMs <= 500) return 'S'\n  if (latencyMs <= 1000) return 'A'\n  if (latencyMs <= 2000) return 'B'\n  return 'C'\n}\n\nconst banKey = (exitId: string, model: string) => `${exitId}\\u0000${model}`\n\nexport class ExitPool {\n  readonly #nodes = new Map<string, ExitNode>()\n  readonly #health = new Map<string, ExitHealth>()\n  readonly #bans = new Map<string, ModelBan>()\n  readonly #sessionExit = new Map<string, string>()\n  /** Passive-signal counters per exit (docs/ip-pool.md §4.3 被动 + IP-6 stats). */\n  readonly #passive = new Map<string, { ok: number; limited: number; refused: number; dead: number; transport: number }>()\n  #targetSize: number\n  #cooldownBase: number\n  #cooldownMax: number\n  #banConfirmations: number\n  #deadEvictions: number\n  #now: () => number\n\n  constructor(options: PoolOptions = {}) {\n    this.#targetSize = options.targetSize ?? 20\n    this.#cooldownBase = options.limitedCooldownBaseMs ?? 60_000\n    this.#cooldownMax = options.limitedCooldownMaxMs ?? 30 * 60_000\n    this.#banConfirmations = options.modelBanConfirmations ?? 2\n    this.#deadEvictions = options.deadEvictions ?? 2\n    this.#now = options.now ?? Date.now\n  }\n\n  /** Live re-apply of the free-pool target capacity (settings page, §5.1). */\n  setTargetSize(value: number): void {\n    this.#targetSize = Math.max(1, value)\n  }\n\n  /** The effective target capacity (diagnostics / status bridge). */\n  get targetSize(): number {\n    return this.#targetSize\n  }\n\n  // -- table management ------------------------------------------------------\n\n  /** Upsert a node (admission wrote its details); returns false on duplicate\n   *  exit IP for a different address — two addresses sharing one exit IP are\n   *  one quota bucket and must not both live in the pool (3.1). */\n  add(node: ExitNode): boolean {\n    if (node.exitIP !== '' && this.#hasExitIP(node.exitIP, node.id)) return false\n    this.#nodes.set(node.id, node)\n    if (!this.#health.has(node.id)) {\n      this.#health.set(node.id, {\n        state: 'unknown',\n        lastProbedAt: 0,\n        consecutiveLimited: 0,\n        cooldownUntil: 0,\n        inflight: false,\n        deadStrikes: 0,\n      })\n    }\n    return true\n  }\n\n  #hasExitIP(exitIP: string, exceptId: string): boolean {\n    for (const node of this.#nodes.values()) {\n      if (node.id !== exceptId && node.exitIP === exitIP) return true\n    }\n    return false\n  }\n\n  has(id: string): boolean {\n    return this.#nodes.has(id)\n  }\n\n  get(id: string): ExitNode | undefined {\n    return this.#nodes.get(id)\n  }\n\n  /** Drop a node entirely (dead eviction for free nodes, cleanup otherwise). */\n  remove(id: string): void {\n    this.#nodes.delete(id)\n    this.#health.delete(id)\n    this.#passive.delete(id)\n    for (const key of this.#bans.keys()) {\n      if (key.startsWith(`${id}\\u0000`)) this.#bans.delete(key)\n    }\n    for (const [session, exitId] of this.#sessionExit) {\n      if (exitId === id) this.#sessionExit.delete(session)\n    }\n    this.#clearPinnedIf(id)\n  }\n\n  /** Disable without dropping (dead manual/subscription/goproxy nodes, 3.5). */\n  markDead(id: string): void {\n    const health = this.#health.get(id)\n    if (!health) return\n    health.state = 'dead'\n    health.inflight = false\n  }\n\n  #clearPinnedIf(id: string): void {\n    if (this.pinnedId === id) this.pinnedId = ''\n  }\n\n  pinnedId = ''\n\n  /** Pin a node (docs/ip-pool.md 3.6); unpinning any previous pinned node. */\n  pin(id: string): boolean {\n    if (!this.#nodes.has(id)) return false\n    this.pinnedId = id\n    return true\n  }\n\n  unpin(): void {\n    this.pinnedId = ''\n  }\n\n  // -- probe locking (4.1: serial per exit) -----------------------------------\n\n  /** Try to take the exit's serial-probe slot; false when already taken. */\n  takeProbeLock(id: string): boolean {\n    const health = this.#health.get(id)\n    if (!health || health.inflight) return false\n    health.inflight = true\n    return true\n  }\n\n  releaseProbeLock(id: string): void {\n    const health = this.#health.get(id)\n    if (health) health.inflight = false\n  }\n\n  // -- passive & probe signals (rule table 4.2) --------------------------------\n\n  markOk(id: string, model?: string): void {\n    const health = this.#health.get(id)\n    if (health) {\n      health.state = 'ok'\n      health.lastProbedAt = this.#now()\n      health.consecutiveLimited = 0\n      health.cooldownUntil = 0\n      health.deadStrikes = 0\n    }\n    if (model !== undefined) {\n      this.#bans.set(banKey(id, model), { state: 'ok', bannedAt: 0, consecutiveFailures: 0 })\n    }\n  }\n\n  /** 429: exit-level cooldown with exponential backoff (3.2 / 4.6). */\n  markLimited(id: string): number {\n    const health = this.#health.get(id)\n    if (!health) return 0\n    health.consecutiveLimited += 1\n    health.state = 'ok'\n    const backoff = Math.min(\n      this.#cooldownBase * 2 ** (health.consecutiveLimited - 1),\n      this.#cooldownMax,\n    )\n    health.cooldownUntil = this.#now() + backoff\n    return health.cooldownUntil\n  }\n\n  /** Deterministic refusal (upstream RegionError: region blocks are a\n   *  property of the exit, not transient noise) — ban the pairing at once. */\n  markModelBanned(id: string, model: string): void {\n    this.#bans.set(banKey(id, model), { state: 'banned', bannedAt: this.#now(), consecutiveFailures: this.#banConfirmations })\n  }\n\n  /** 401/403: model-level suspicion; banned after N consecutive (3.2). */\n  markModelSignal(id: string, model: string): BanState {\n    const key = banKey(id, model)\n    const current = this.#bans.get(key) ?? { state: 'ok' as BanState, bannedAt: 0, consecutiveFailures: 0 }\n    current.consecutiveFailures += 1\n    if (current.consecutiveFailures >= this.#banConfirmations && current.state !== 'banned') {\n      current.state = 'banned'\n      current.bannedAt = this.#now()\n    } else if (current.state !== 'banned') {\n      current.state = 'suspect'\n    }\n    this.#bans.set(key, current)\n    return current.state\n  }\n\n  /** Transport failure / 5xx / probe timeout: dead, with free-source eviction\n   *  after repeated strikes (3.5). Returns true when the node was evicted. */\n  markDeadStrike(id: string): boolean {\n    const node = this.#nodes.get(id)\n    const health = this.#health.get(id)\n    if (!node || !health) return false\n    health.state = 'dead'\n    health.inflight = false\n    health.deadStrikes += 1\n    if (node.source === 'free' && health.deadStrikes >= this.#deadEvictions) {\n      this.remove(id)\n      return true\n    }\n    return false\n  }\n\n  /** Death from a mid-flight stream (no retry path): same strike accounting. */\n  markStreamFailure(id: string, kind: '429' | 'model', model?: string): void {\n    if (kind === '429') {\n      this.markLimited(id)\n      this.#countPassive(id, 'limited')\n    } else if (model !== undefined) {\n      this.markModelSignal(id, model)\n      this.#countPassive(id, 'refused')\n    }\n  }\n\n  /**\n   * Passive signal from a REAL request outcome (docs/ip-pool.md §4.2 rule\n   * table, §4.3 被动 row): one response header read at the routing layer,\n   * applied to the two-tier health exactly like a probe would. Returns the\n   * classification for diagnostics.\n   */\n  recordPassive(id: string, statusCode: number, model: string, regionBlocked = false): 'ok' | 'limited' | 'refused' | 'dead' {\n    if (!this.#nodes.has(id)) return 'ok'\n    if (statusCode >= 200 && statusCode < 300) {\n      this.markOk(id, model)\n      this.#countPassive(id, 'ok')\n      return 'ok'\n    }\n    if (statusCode === 429) {\n      this.markLimited(id)\n      this.#countPassive(id, 'limited')\n      return 'limited'\n    }\n    if (statusCode === 401 || statusCode === 403) {\n      // RegionError bodies are deterministic region blocks — a second sample\n      // adds nothing, so ban the (exit, model) pairing immediately (docs 4.2).\n      if (regionBlocked) this.markModelBanned(id, model)\n      else this.markModelSignal(id, model)\n      this.#countPassive(id, 'refused')\n      return 'refused'\n    }\n    // 5xx: count into the dead bucket for diagnostics, but DO NOT strike the\n    // exit dead. Live-observed 2026-09-09: upstream 500s are often the MODEL\n    // failing behind a healthy exit (muse without contributor access answers\n    // 500 through every exit) — one strike used to mark the exit dead, the\n    // single-exit pool then picked null, and ALL traffic silently fell back\n    // direct while the pool looked enabled. Exit liveness stays the\n    // transport layer's call (sentinel/onResponseError); recovery for a\n    // 5xx-flapping exit is the adapter rotate loop (5xx is in its set).\n    this.#countPassive(id, 'dead')\n    return 'dead'\n  }\n\n  /** Transport-level failure of a real request (connection died mid-flight). */\n  recordPassiveTransport(id: string): void {\n    if (!this.#nodes.has(id)) return\n    this.markDeadStrike(id)\n    this.#countPassive(id, 'transport')\n  }\n\n  /** Drop the session's sticky exit when its exit degraded (§3.3). */\n  rerouteSession(session: string): void {\n    this.#sessionExit.delete(session)\n  }\n\n  /** The session's current sticky exit, if any (adapter-side 403 bookkeeping:\n   *  the dispatcher recorded the refusal against this exit). */\n  exitOfSession(session: string): string | null {\n    return this.#sessionExit.get(session) ?? null\n  }\n\n  #countPassive(id: string, kind: 'ok' | 'limited' | 'refused' | 'dead' | 'transport'): void {\n    const bucket = this.#passive.get(id) ?? { ok: 0, limited: 0, refused: 0, dead: 0, transport: 0 }\n    if (kind === 'limited') bucket.limited += 1\n    else if (kind === 'refused') bucket.refused += 1\n    else if (kind === 'dead') bucket.dead += 1\n    else if (kind === 'transport') bucket.transport += 1\n    else bucket.ok += 1\n    this.#passive.set(id, bucket)\n  }\n\n  /** Passive-signal counters for one exit (status bridge, IP-6). */\n  passiveStats(id: string): { ok: number; limited: number; refused: number; dead: number; transport: number } {\n    return { ...(this.#passive.get(id) ?? { ok: 0, limited: 0, refused: 0, dead: 0, transport: 0 }) }\n  }\n\n  // -- selection (3.3) ---------------------------------------------------------\n\n  isUsable(id: string, model: string): boolean {\n    const health = this.#health.get(id)\n    if (!health || health.state === 'dead') return false\n    if (health.cooldownUntil > this.#now()) return false\n    const ban = this.#bans.get(banKey(id, model))\n    return ban?.state !== 'banned'\n  }\n\n  /**\n   * Pick the exit for one upstream request. Pinned wins while usable (3.6);\n   * the rotation pool then prefers session stickiness, health, fewer\n   * cooldowns and lower latency with a same-tier shuffle. Pure; no IO.\n   */\n  pick(session: string, model: string): string | null {\n    if (this.pinnedId !== '' && this.isUsable(this.pinnedId, model)) return this.pinnedId\n\n    const last = this.#sessionExit.get(session)\n    if (last !== undefined && this.isUsable(last, model)) return last\n\n    const usable = [...this.#nodes.keys()].filter((id) => this.isUsable(id, model))\n    if (usable.length === 0) return null\n    const health = (id: string) => this.#health.get(id)!\n    const node = (id: string) => this.#nodes.get(id)!\n    usable.sort((left, right) => {\n      const a = health(left)\n      const b = health(right)\n      const stateRank = (h: ExitHealth) => (h.state === 'ok' ? 0 : 1)\n      const byState = stateRank(a) - stateRank(b)\n      if (byState !== 0) return byState\n      const byLimited = a.consecutiveLimited - b.consecutiveLimited\n      if (byLimited !== 0) return byLimited\n      const byLatency = node(left).latencyMs - node(right).latencyMs\n      if (byLatency !== 0) return byLatency\n      return Math.random() < 0.5 ? -1 : 1\n    })\n    const chosen = usable[0]\n    if (chosen === undefined) return null\n    this.#sessionExit.set(session, chosen)\n    return chosen\n  }\n\n  /** Drop the session's sticky exit (cooldown/dead/ban broke it). */\n  breakStickySession(session: string): void {\n    this.#sessionExit.delete(session)\n  }\n\n  // -- four-state machine (3.5) -------------------------------------------------\n\n  /** Usable = not dead, not cooling, and not banned for every probe model —\n   *  approximation: nodes banned for all their known models count as\n   *  unusable; with no ban data they stay usable (they are only banned for\n   *  specific models, which the caller's model already filters). */\n  #isAvailable(id: string): boolean {\n    const health = this.#health.get(id)\n    if (!health || health.state === 'dead') return false\n    if (health.cooldownUntil > this.#now()) return false\n    // A node with at least one banned pairing and no healthy pairing for any\n    // model it serves is effectively exhausted. Track by distinct models:\n    const nodeModels = new Set<string>()\n    let allBanned = true\n    let sawBan = false\n    for (const [key, ban] of this.#bans) {\n      if (!key.startsWith(`${id}\\u0000`)) continue\n      const model = key.slice(id.length + 1)\n      nodeModels.add(model)\n      if (ban.state !== 'banned') allBanned = false\n      else sawBan = true\n    }\n    if (sawBan && nodeModels.size > 0 && allBanned) return false\n    return true\n  }\n\n  /** Count usable free-source nodes toward the refill thresholds. */\n  availableFreeCount(): number {\n    let count = 0\n    for (const node of this.#nodes.values()) {\n      if (node.source === 'free' && this.#isAvailable(node.id)) count += 1\n    }\n    return count\n  }\n\n  /** Determine the pool state over the free-source pool (3.5 thresholds). */\n  state(): PoolState {\n    if (this.#targetSize <= 0) return 'healthy'\n    const available = this.availableFreeCount()\n    const ratio = available / this.#targetSize\n    if (ratio < 0.1) return 'emergency'\n    if (ratio < 0.3) return 'critical'\n    if (ratio < 0.95) return 'warning'\n    return 'healthy'\n  }\n\n  /** Admission quota for a refill round: how many free nodes to accept. */\n  admissionQuota(): number {\n    return Math.max(0, this.#targetSize - this.availableFreeCount())\n  }\n\n  /** Replace the worst free node (C grade / oldest) to make room (3.5). */\n  evictWorstFree(): boolean {\n    let worst: ExitNode | null = null\n    for (const node of this.#nodes.values()) {\n      if (node.source !== 'free') continue\n      if (!worst) {\n        worst = node\n        continue\n      }\n      const gradeRank: Record<ExitNode['quality'], number> = { S: 0, A: 1, B: 2, C: 3 }\n      const byGrade = gradeRank[node.quality] - gradeRank[worst.quality]\n      if (byGrade > 0 || (byGrade === 0 && node.addedAt < worst.addedAt)) worst = node\n    }\n    if (!worst) return false\n    this.remove(worst.id)\n    return true\n  }\n\n  /** Is the pool full for free-source admission? (pinned and non-free nodes\n   *  never count against the target, 3.5/3.6.) */\n  isFreeFull(): boolean {\n    return this.freeCount() >= this.#targetSize\n  }\n\n  freeCount(): number {\n    let count = 0\n    for (const node of this.#nodes.values()) if (node.source === 'free') count += 1\n    return count\n  }\n\n  // -- diagnostics ------------------------------------------------------------\n\n  snapshot(): {\n    state: PoolState\n    total: number\n    bySource: Record<ExitSource, number>\n    availableFree: number\n    pinned: string\n  } {\n    const bySource: Record<ExitSource, number> = { free: 0, manual: 0, subscription: 0, goproxy: 0 }\n    for (const node of this.#nodes.values()) bySource[node.source] += 1\n    return {\n      state: this.state(),\n      total: this.#nodes.size,\n      bySource,\n      availableFree: this.availableFreeCount(),\n      pinned: this.pinnedId,\n    }\n  }\n\n  list(): Array<ExitNode & { health: ExitHealth; bans: Array<{ model: string; ban: ModelBan }> }> {\n    const out: Array<ExitNode & { health: ExitHealth; bans: Array<{ model: string; ban: ModelBan }> }> = []\n    for (const [id, node] of this.#nodes) {\n      const health = this.#health.get(id)!\n      const bans: Array<{ model: string; ban: ModelBan }> = []\n      for (const [key, ban] of this.#bans) {\n        if (key.startsWith(`${id}\\u0000`)) bans.push({ model: key.slice(id.length + 1), ban })\n      }\n      out.push({ ...node, health, bans })\n    }\n    return out\n  }\n}\n"
    }
  ],
